describe('File Upload Queue', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Replace with the actual URL of the upload page
    });

    it('should remove a file from the upload queue before submitting', () => {
        const fileName = 'example-file.txt';
        cy.get('input[type="file"]').attachFile(fileName); // Assuming you have a file upload input
        cy.get('.upload-queue').should('contain', fileName); // Check if the file is in the queue

        cy.get('.remove-file-button').first().click(); // Assuming there's a button to remove the first file
        cy.get('.upload-queue').should('not.contain', fileName); // Verify the file is removed
    });

    it('should not allow submission if the upload queue is empty', () => {
        cy.get('.submit-button').click(); // Attempt to submit without files
        cy.get('.error-message').should('be.visible').and('contain', 'Upload queue is empty'); // Check for error message
    });
});
